func adCells2(c *port.Cells, a int32, b int32) int32 {
	port.CellsDrop(c, 0)
	port.CellsPush(c, a)
	port.CellsPush(c, b)
	return 0
}

func adCells1(c *port.Cells, a int32) int32 {
	port.CellsDrop(c, 0)
	port.CellsPush(c, a)
	return 0
}

func adRegTess(abi int32, caps int32, measured int32, needs int32, flags int32) int32 {
	return adapters.AdRegisterCheck(abi, oil.OenTesseract(), caps, measured, needs, flags)
}

func adResolve(pclass int32, flags int32, langs *port.Cells, engs *port.Cells, installed *port.Cells, out *port.Cells) int32 {
	var scratch *port.Cells = port.NewCells()
	return engines.PkResolve(pclass, flags, langs, engs, installed, out, scratch)
}

func TestTheAbiAndItsFlagsAreTheOnesTheHeaderDeclares(emonT *testing.T) {
	port.AssertEq(emonT, adapters.AdAbi(), 1, "EMON_ADAPTER_ABI is 1")
	port.AssertEq(emonT, adapters.AdfAsync(), 1, "EMON_ADAPTER_ASYNC")
	port.AssertEq(emonT, adapters.AdfRemote(), 2, "EMON_ADAPTER_REMOTE")
	port.AssertEq(emonT, adapters.AdfThreadsafe(), 4, "EMON_ADAPTER_THREADSAFE")
	port.AssertEq(emonT, adapters.AdfKnown(), 7, "the three")
	port.AssertEq(emonT, adapters.AdsOk(), 0, "EMON_ADAPTER_OK")
	port.AssertEq(emonT, adapters.AdsUnsupported(), 1, "EMON_ADAPTER_UNSUPPORTED")
	port.AssertEq(emonT, adapters.AdsFailed(), 2, "EMON_ADAPTER_FAILED")
}

func TestAnAdapterIsTheEngineOfTheTableItsOilCodeNames(emonT *testing.T) {
	port.AssertEq(emonT, adapters.AdOenEng(oil.OenTesseract()), engines.EngTesseract(), "Tesseract")
	port.AssertEq(emonT, adapters.AdOenEng(oil.OenPpocr()), engines.EngPpocr(), "PP-OCR is the native row, not the web one")
	port.AssertEq(emonT, adapters.AdOenEng(oil.OenAppleVision()), engines.EngAppleVision(), "Vision")
	port.AssertEq(emonT, adapters.AdOenEng(99), -1, "no such OIL engine")
	port.AssertEq(emonT, adapters.AdOenEng(0), -1, "0 is no engine")
}

func TestEveryEngineOfTheTableRegistersWithExactlyItsCeiling(emonT *testing.T) {
	var i int32 = 0
	var n int32 = 0
	var eng int32 = 0
	for i < engines.PkEngineCount() {
		eng = engines.PkEngineAt(i)
		if engines.PkEngineKind(eng) == engines.EkindOcr() {
			port.AssertEq(emonT, adapters.AdRegisterCheck(adapters.AdAbi(), engines.PkEngineOen(eng), engines.PkEngineCaps(eng), 0, engines.PkEngineNeeds(eng), 0), adapters.AdrOk(), "an adapter declaring what the table allows is accepted")
			port.AssertEq(emonT, adapters.AdRegisterCheck(adapters.AdAbi(), engines.PkEngineOen(eng), engines.PkEngineCaps(eng), engines.PkEngineCaps(eng), engines.PkEngineNeeds(eng), adapters.AdfKnown()), adapters.AdrOk(), "and every flag, and every capability measured")
			port.AssertEq(emonT, adapters.AdRegisterCheck(adapters.AdAbi(), engines.PkEngineOen(eng), 0, 0, 0, 0), adapters.AdrOk(), "declaring nothing is a smaller ceiling, not a violation")
			n += 1
		}
		i += 1
	}
	port.AssertThat(emonT, n >= 6, "the table has at least six OCR engines")
}

