func TestARegistrationIsRefusedByNameForEachThingItGetsWrong(emonT *testing.T) {
	port.AssertEq(emonT, adRegTess(2, 1, 0, 1, 0), adapters.AdrAbi(), "an ABI newer than this library's")
	port.AssertEq(emonT, adRegTess(0, 1, 0, 1, 0), adapters.AdrAbi(), "an ABI of 0 is no ABI")
	port.AssertEq(emonT, adapters.AdRegisterCheck(1, 99, 1, 0, 1, 0), adapters.AdrEngine(), "an OIL engine the table does not have")
	port.AssertEq(emonT, adapters.AdRegisterCheck(1, 0, 1, 0, 1, 0), adapters.AdrEngine(), "OIL engine 0")
	port.AssertEq(emonT, adapters.AdRegisterCheck(1, oil.OenPpocr(), 8388608, 0, 0, 0), adapters.AdrCaps(), "a capability bit beyond what PP-OCR may declare")
	port.AssertEq(emonT, adapters.AdRegisterCheck(1, oil.OenPpocr(), 8, 8, 0, 0), adapters.AdrCaps(), "baselines are Tesseract's, not PP-OCR's")
	port.AssertEq(emonT, adRegTess(1, 1, 3, 1, 0), adapters.AdrNative(), "measured capabilities the adapter does not declare")
	port.AssertEq(emonT, adapters.AdRegisterCheck(1, oil.OenAppleVision(), 32, 0, 1, 0), adapters.AdrNeeds(), "Vision reads with no pack")
	port.AssertEq(emonT, adRegTess(1, 1, 0, 4, 0), adapters.AdrNeeds(), "a detector is not a Tesseract pack kind")
	port.AssertEq(emonT, adRegTess(1, 1, 0, 1, 8), adapters.AdrFlags(), "a flag the ABI does not define")
}

