func TestARequestGoesToTheAdapterOfItsEngine(emonT *testing.T) {
	var reg *port.Cells = port.NewCells()
	adCells2(reg, oil.OenTesseract(), oil.OenPpocr())
	port.AssertEq(emonT, adapters.AdRoute(oil.OenTesseract(), reg, 0), 0, "Tesseract's request to the first")
	port.AssertEq(emonT, adapters.AdRoute(oil.OenPpocr(), reg, 0), 1, "PP-OCR's request to the second")
	adCells2(reg, oil.OenPpocr(), oil.OenTesseract())
	port.AssertEq(emonT, adapters.AdRoute(oil.OenTesseract(), reg, 0), 1, "by engine, not by position")
	port.AssertEq(emonT, adapters.AdRoute(oil.OenPpocr(), reg, 0), 0, "the other way round")
}

