func TestARequestForAnEngineNobodyRegisteredIsUnsupportedOrTheCallers(emonT *testing.T) {
	var reg *port.Cells = port.NewCells()
	adCells1(reg, oil.OenTesseract())
	port.AssertEq(emonT, adapters.AdRoute(oil.OenPpocr(), reg, 0), adapters.AdRouteUnsupported(), "unsupported, so the page is unread")
	port.AssertEq(emonT, adapters.AdRoute(oil.OenPpocr(), reg, 1), adapters.AdRouteCaller(), "the caller owes what nobody registered (js-ocr=1)")
	port.AssertEq(emonT, adapters.AdRoute(oil.OenTesseract(), reg, 1), 0, "but what an adapter is registered for stays the adapter's")
	port.CellsDrop(reg, 0)
	port.AssertEq(emonT, adapters.AdRoute(oil.OenTesseract(), reg, 0), adapters.AdRouteUnsupported(), "no adapter at all: unsupported")
	port.AssertEq(emonT, adapters.AdRoute(oil.OenTesseract(), reg, 1), adapters.AdRouteCaller(), "or the caller's")
	port.AssertThat(emonT, adapters.AdRouteUnsupported() < 0, "neither is an index")
	port.AssertThat(emonT, adapters.AdRouteCaller() < 0, "neither is an index")
	port.AssertThat(emonT, adapters.AdRouteCaller() != adapters.AdRouteUnsupported(), "and they differ")
}

func TestAnAnswerIsHeldToWhatItsAdapterRegistered(emonT *testing.T) {
	port.AssertEq(emonT, adapters.AdAnswerCheck(oil.OenTesseract(), 7339791, oil.OenTesseract(), oil.OenTesseract(), 2225423), adapters.AdaOk(), "within the registered capabilities")
	port.AssertEq(emonT, adapters.AdAnswerCheck(oil.OenTesseract(), 7339791, 0, oil.OenTesseract(), 7339791), adapters.AdaOk(), "a request with no trailer was Tesseract's")
	port.AssertEq(emonT, adapters.AdAnswerCheck(oil.OenTesseract(), 7339791, oil.OenTesseract(), oil.OenPpocr(), 24928), adapters.AdaEngine(), "an answer in another engine's name")
	port.AssertEq(emonT, adapters.AdAnswerCheck(oil.OenPpocr(), 24928, oil.OenTesseract(), oil.OenPpocr(), 24928), adapters.AdaRequest(), "an adapter handed another engine's request")
	port.AssertEq(emonT, adapters.AdAnswerCheck(oil.OenTesseract(), 1, oil.OenTesseract(), oil.OenTesseract(), 3), adapters.AdaCaps(), "capabilities the adapter never registered")
	port.AssertEq(emonT, adapters.AdAnswerCheck(oil.OenTesseract(), 1, oil.OenTesseract(), oil.OenTesseract(), 0), adapters.AdaOk(), "fewer capabilities are fine")
}

