func TestNeverAndOfflineWinOverEveryHook(emonT *testing.T) {
	port.AssertEq(emonT, adapters.AdPackAction(0, engines.PfetchNever(), 0, 1, adapters.PdecFetch()), adapters.PactUnread(), "never: a fetch answer is not honoured")
	port.AssertEq(emonT, adapters.AdPackAction(0, engines.PfetchNever(), 0, 1, adapters.PdecProvide()), adapters.PactUnread(), "never: nor a provide")
	port.AssertEq(emonT, adapters.AdPackAction(0, engines.PfetchNever(), 0, 1, adapters.PdecSubstitute()), adapters.PactUnread(), "never: nor a substitute")
	port.AssertEq(emonT, adapters.AdPackAction(0, engines.PfetchNever(), 0, 0, 0), adapters.PactUnread(), "never with no hook: unread")
	port.AssertEq(emonT, adapters.AdPackAction(0, engines.PfetchAuto(), 1, 1, adapters.PdecFetch()), adapters.PactUnread(), "EMON_OFFLINE=1 in auto: unread")
	port.AssertEq(emonT, adapters.AdPackAction(0, engines.PfetchAuto(), 1, 0, 0), adapters.PactUnread(), "EMON_OFFLINE=1 with no hook: unread")
	port.AssertEq(emonT, adapters.AdPackAction(0, engines.PfetchCache(), 1, 1, adapters.PdecProvide()), adapters.PactUnread(), "EMON_OFFLINE=1 in cache: unread")
	port.AssertEq(emonT, adapters.AdAsksHook(0, engines.PfetchNever(), 0, 1), 0, "the hook is not even asked under never")
	port.AssertEq(emonT, adapters.AdAsksHook(0, engines.PfetchAuto(), 1, 1), 0, "nor offline")
}

